using BmsDesktop.Infrastructure;
using Npgsql;
namespace BmsDesktop.Rhpp;
public sealed record RhppResult(decimal DocReceived,decimal Mortality,decimal HarvestBirds,decimal HarvestKg,decimal FeedKg,decimal MortalityPct,decimal AvgBwKg,decimal Fcr,decimal Ip,decimal? ContractBwPrice,decimal? ContractRevenue,decimal ExtraFeedSapronak,decimal Abk,decimal Bop,decimal AdditionalMeatActualCost,decimal? OperationalProfit);
public sealed class RhppCalculationService { private readonly Database _db;private readonly ContractPriceService _prices;public RhppCalculationService(Database db){_db=db;_prices=new(db);}public async Task<RhppResult> CalculateAsync(Guid cycle){await using var cn=await _db.OpenAsync();async Task<decimal> Q(string s){await using var c=new NpgsqlCommand(s,cn);c.Parameters.AddWithValue("id",cycle);return Convert.ToDecimal(await c.ExecuteScalarAsync()??0m);}var doc=await Q("select coalesce(received_qty,0) from doc_intakes where cycle_id=@id");var mort=await Q("select coalesce(sum(mortality_qty+cull_qty),0) from daily_recordings where cycle_id=@id");var birds=await Q("select coalesce(sum(bird_qty),0) from harvests where cycle_id=@id and status='POSTED'");var kg=await Q("select coalesce(sum(total_weight_kg),0) from harvests where cycle_id=@id and status='POSTED'");var feed=await Q("select coalesce(sum(quantity_kg),0) from feed_usage where cycle_id=@id");var age=await Q("select coalesce(max(age_day),0) from daily_recordings where cycle_id=@id");var extra=await Q("select coalesce(sum(amount),0) from extra_sapronak where cycle_id=@id")+await Q("select coalesce(sum(quantity_kg),0) from feed_usage where cycle_id=@id and source='EXTRA'");var abk=await Q("select coalesce(sum(amount),0) from abk_work_entries where cycle_id=@id");var bop=await Q("select coalesce(sum(amount),0) from barn_operational_costs where cycle_id=@id");var meat=await Q("select coalesce(sum(actual_amount),0) from additional_meat_purchases where cycle_id=@id");var m=RhppMetricsCalculator.Calculate(doc,mort,birds,kg,feed,age);var price=await _prices.GetBwPriceAsync(cycle,m.AvgBodyWeightKg);decimal? revenue=price.HasValue?kg*price.Value:null;decimal? profit=revenue.HasValue?revenue.Value-extra-abk-bop:null;return new(doc,mort,birds,kg,feed,m.MortalityPct,m.AvgBodyWeightKg,m.Fcr,m.Ip,price,revenue,extra,abk,bop,meat,profit);} }
